import base64
import pandas as pd
from io import StringIO
from pyspark.sql import functions as F

Ledger_base64_string = """

"""  # must not be empty

if not Ledger_base64_string.strip():
    raise ValueError("Base64 string is empty. Paste a valid Base64 CSV.")

# 1) Decode -> pandas
decoded = base64.b64decode(Ledger_base64_string)
csv_str = decoded.decode("utf-8")

# If CSV might be empty:
if not csv_str.strip():
    raise ValueError("Decoded CSV is empty.")

pdf = pd.read_csv(StringIO(csv_str))

# 2) Parse dates in pandas (adjust format if needed)
#   Example expects dd/mm/yyyy HH:MM. If you have mm/dd/yyyy, change to '%m/%d/%Y %H:%M'.
pdf["Date"] = pd.to_datetime(pdf["Date"], format="%d/%m/%Y %H:%M", errors="coerce")

# 3) Convert pandas -> Spark
sdf = spark.createDataFrame(pdf)

# 4) Ensure proper Spark timestamp type for Date
sdf = sdf.withColumn(
    "Date",
    F.to_timestamp(F.col("Date").cast("timestamp"))  # idempotent if already timestamp
)



